<script setup lang="ts">
import {reactive,ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import {useI18n} from 'vue-i18n'
import {useAccount} from '../store'
import {api} from '../api'
import FieldInput from '../components/FieldInput.vue'
const {t}=useI18n(),account=useAccount(), form=reactive({...account.user}),password=reactive({old_password:'',new_password:'',new_password_confirm:''})
const passwordRef=ref(),formRef=ref(),genders=ref<any[]>([]),messages=ref<any[]>([])
const passwordRules={old_password:[{required:true,message:'请填写原密码'}],new_password:[{required:true,message:'请填写新密码'},{validator:(_rule:any,value:string)=>value!==password.old_password||new Error('新密码不能与原密码相同')}],new_password_confirm:[{required:true,message:'请确认新密码'},{validator:(_rule:any,value:string)=>value===password.new_password||new Error('两次密码不匹配')}]}
onMounted(async()=>{genders.value=(await api('/api/dictionary/',{params:{key:'gender'}})).data;messages.value=(await api('/api/inbox/')).data.messages})
async function save(){if(!await formRef.value.validate(()=>{}))return;await api('/api/account/',{method:'PATCH',data:{name:form.name,email:form.email,mobile:form.mobile,avatar:form.avatar,gender:form.gender}});await account.load();ElMessage.success(t('profileSaved'))}
async function change(){if(!await passwordRef.value.validate(()=>{}))return;await api('/api/password/',{method:'POST',data:password});password.old_password='';password.new_password='';password.new_password_confirm='';await account.load();ElMessage.success(t('passwordSaved'))}
</script>
<template><div class="page profile"><h2>{{t('account')}}</h2><el-card header="个人资料"><el-descriptions :column="1"><el-descriptions-item label="账号">{{account.user.username}}</el-descriptions-item><el-descriptions-item label="部门">{{account.user.dept_name}}</el-descriptions-item><el-descriptions-item label="角色"><el-tag v-for="role in account.user.role_info" :key="role.id">{{role.name}}</el-tag></el-descriptions-item></el-descriptions><el-form ref="formRef" :model="form" label-width="100px"><el-form-item label="头像"><FieldInput v-model="form.avatar" :field="{key:'avatar',kind:'avatar',options:[]}"/></el-form-item><el-form-item label="姓名" prop="name" :rules="[{required:true,message:'请填写姓名'}]"><el-input v-model="form.name"/></el-form-item><el-form-item label="性别"><FieldInput v-model="form.gender" :field="{key:'gender',kind:'select',options:genders}"/></el-form-item><el-form-item label="邮箱" prop="email" :rules="[{type:'email',message:'邮箱格式不正确'}]"><el-input v-model="form.email"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.mobile"/></el-form-item><el-form-item><el-button type="primary" @click="save">{{t('save')}}</el-button></el-form-item></el-form></el-card><el-card :header="t('newPassword')"><el-form ref="passwordRef" :model="password" :rules="passwordRules" label-width="140px"><el-form-item prop="old_password" :label="t('oldPassword')"><el-input v-model="password.old_password" type="password" show-password/></el-form-item><el-form-item prop="new_password" :label="t('newPassword')"><el-input v-model="password.new_password" type="password" show-password/></el-form-item><el-form-item prop="new_password_confirm" :label="t('confirmPassword')"><el-input v-model="password.new_password_confirm" type="password" show-password/></el-form-item><el-form-item><el-button type="primary" @click="change">{{t('save')}}</el-button></el-form-item></el-form></el-card><el-card header="最近消息"><el-empty v-if="!messages.length" description="暂无消息"/><div v-for="message in messages" :key="message.id" class="recent-message"><el-link @click="$router.push('/inbox?id='+message.id)">{{message.title}}</el-link><el-tag v-if="!message.is_read" size="small">未读</el-tag><small>{{message.sender}} · {{message.time}}</small></div></el-card></div></template>
<style scoped>.recent-message{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.recent-message small{color:var(--el-text-color-secondary)}</style>

